UPDATE words w SET cum_weight = s.running FROM (SELECT locale, category, idx, sum(weight) OVER (PARTITION BY locale, category ORDER BY idx) AS running FROM words) s WHERE (w.locale, w.category, w.idx) = (s.locale, s.category, s.idx);
